/* ============================================ */
/* CHIYAZ TEA & COFFEE - PREMIUM STYLING (FIXED) */
/* ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* ✅ PERSISTENT BACKGROUND IMAGE */
body::before {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?q=80&w=2070&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  background-repeat: no-repeat;
  z-index: -2;
}

body::after {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(44, 24, 16, 0.85);
  backdrop-filter: blur(3px);
  z-index: -1;
}

/* ============================================ */
/* BASE STYLES - Tea & Coffee Theme */
/* ============================================ */
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  background: transparent !important;
  color: #F5E9D9 !important;
  min-height: 100vh;
  transition: all 0.6s ease;
  overflow-x: hidden;
  position: relative;
}

/* ============================================ */
/* DARK MODE - Coffee Shop Vibes */
/* ============================================ */
body.dark-mode::after {
  background: rgba(26, 18, 11, 0.9) !important;
}

body.dark-mode {
  color: #F5E9D9 !important;
}

/* Navbar links in dark mode */
body.dark-mode nav a,
body.dark-mode nav button {
  color: #F5E9D9 !important;
  transition: all 0.2s ease;
}

body.dark-mode nav a:hover,
body.dark-mode nav button:hover {
  color: #D2691E !important;
  background: rgba(212, 185, 150, 0.1) !important;
}

/* ============================================ */
/* CUSTOMER REVIEWS - FORCE DARK BACKGROUNDS */
/* ============================================ */

/* Override ALL review cards with !important */
.customer-review-card,
.review-card,
.testimonial-card,
[class*="review-card"],
[class*="testimonial-card"],
section div[style*="background"][style*="white"] {
  background: rgba(44, 24, 16, 0.85) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(212, 185, 150, 0.2) !important;
  border-radius: 20px !important;
  color: #F5E9D9 !important;
}

/* Review card ALL text elements */
.customer-review-card *,
.review-card *,
.testimonial-card *,
[class*="review-card"] *,
[class*="testimonial-card"] * {
  color: #F5E9D9 !important;
}

/* Review summary sidebar */
.review-summary,
.rating-summary,
[class*="summary"],
section > div > div[style*="flex: 0 0 280px"] {
  background: rgba(44, 24, 16, 0.85) !important;
  border: 1px solid rgba(212, 185, 150, 0.2) !important;
  border-radius: 20px !important;
  color: #F5E9D9 !important;
}

/* Rating stars */
.rating,
[class*="rating"],
span[style*="color"][style*="#fbbf24"] {
  color: #D2691E !important;
}

/* Write review button */
.write-review-btn,
button[onclick*="review"],
button[style*="#667eea"] {
  background: linear-gradient(135deg, #8B4513 0%, #D2691E 100%) !important;
  color: #F5E9D9 !important;
}

/* ============================================ */
/* PROJECT GRID - Tea & Coffee Cards */
/* ============================================ */
.project-grid-item,
.product-card,
.item-card,
.grid-item,
.project-card,
[class*="grid-item"],
[class*="product-card"],
[class*="item-card"] {
  background: rgba(44, 24, 16, 0.85) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(212, 185, 150, 0.2) !important;
  border-radius: 20px !important;
  color: #F5E9D9 !important;
  overflow: hidden !important;
  transition: all 0.3s ease !important;
}

.project-grid-item:hover,
.product-card:hover,
.item-card:hover {
  transform: translateY(-10px) !important;
  box-shadow: 0 20px 40px rgba(139, 69, 19, 0.3) !important;
  border: 1px solid rgba(212, 185, 150, 0.4) !important;
}

/* Glass card styling */
.glass-card {
  background: rgba(44, 24, 16, 0.85) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(212, 185, 150, 0.2) !important;
  box-shadow: 0 8px 32px 0 rgba(139, 69, 19, 0.25) !important;
  color: #F5E9D9 !important;
}

/* Card text visibility */
.glass-card h1,
.glass-card h2,
.glass-card h3,
.glass-card p,
.glass-card span {
  color: #F5E9D9 !important;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
}

/* Navbar styling */
body nav,
body header {
  background: rgba(44, 24, 16, 0.95) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border-bottom: 2px solid rgba(212, 185, 150, 0.3) !important;
  color: #F5E9D9 !important;
}

body.dark-mode nav,
body.dark-mode header {
  background: rgba(30, 18, 11, 0.95) !important;
  border-bottom: 2px solid rgba(212, 185, 150, 0.3) !important;
}

body nav a,
body header a,
body nav button,
body header button {
  color: #F5E9D9 !important;
  font-weight: 500 !important;
}

/* Button styling */
.primary-btn {
  background: linear-gradient(135deg, #8B4513 0%, #D2691E 100%) !important;
  color: #F5E9D9 !important;
  border: none !important;
  border-radius: 25px !important;
  padding: 12px 30px !important;
  font-weight: 600 !important;
  transition: all 0.3s ease !important;
}

.primary-btn:hover {
  transform: translateY(-3px) !important;
  box-shadow: 0 10px 20px rgba(139, 69, 19, 0.5) !important;
}

/* Input fields */
input, textarea, select {
  background: rgba(245, 233, 217, 0.1) !important;
  border: 1px solid rgba(212, 185, 150, 0.3) !important;
  color: #F5E9D9 !important;
  padding: 12px 16px !important;
  border-radius: 10px !important;
}

input::placeholder,
textarea::placeholder {
  color: rgba(245, 233, 217, 0.6) !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: rgba(139, 69, 19, 0.1);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(135deg, #8B4513 0%, #D2691E 100%);
  border-radius: 10px;
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Responsive */
@media (max-width: 768px) {
  .hero-title {
    font-size: 2.5rem !important;
  }

  .hero-subtitle {
    font-size: 1.1rem !important;
  }

  nav {
    padding: 15px 20px !important;
  }

  .glass-card {
    padding: 25px !important;
  }

  .project-grid-item,
  .customer-review-card {
    margin-bottom: 20px !important;
  }
}

actions.openReviewModal:
console.log('🎭 Opening review modal');
context.handlers.setModalFormData({});
context.handlers.setFieldErrors({});
context.handlers.setActiveModal('writeReview');
console.log('✅ Review modal opened');

actions.submitReview:
console.log('📝 Submitting review');
const formData = context.modalFormData || {};
console.log('📦 Review form data:', formData);
const errors = {};
if (!formData.reviewerName || formData.reviewerName.trim().length < 2) {
  errors.reviewerName = 'Name must be at least 2 characters';
}
if (!formData.rating || formData.rating < 1 || formData.rating > 5) {
  errors.rating = 'Please select a rating (1-5 stars)';
}
if (!formData.comment || formData.comment.trim().length < 10) {
  errors.comment = 'Review must be at least 10 characters';
}
if (Object.keys(errors).length > 0) {
  console.error('❌ Validation errors:', errors);
  context.handlers.setFieldErrors(errors);
  context.handlers.showNotification({
    type: 'toast',
    message: '❌ Please fix the errors in the form',
    background: '#8B4513',
    duration: 3000
  });
  return;
}
context.handlers.setFieldErrors({});
console.log('🚀 Calling chiyaz.reviews.submit API');
await context.handlers.handleApiCall('chiyaz.reviews.submit', formData);
console.log('✅ Review submitted successfully');

actions.closeReviewModal:
console.log('❌ Closing review modal');
context.handlers.setModalFormData({});
context.handlers.setFieldErrors({});
context.handlers.setActiveModal(null);
console.log('✅ Modal closed and data cleared');

actions.toggleTheme:
const body = document.body;
const isDark = body.classList.contains('dark-mode');
if (isDark) {
  body.classList.remove('dark-mode');
  localStorage.setItem('chiyaz-theme', 'light');
  console.log('☀️ Light mode activated');
} else {
  body.classList.add('dark-mode');
  localStorage.setItem('chiyaz-theme', 'dark');
  console.log('🌙 Dark mode activated');
}

actions.loadTheme:
const saved = localStorage.getItem('chiyaz-theme');
const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
if (saved === 'dark' || (!saved && prefersDark)) {
  document.body.classList.add('dark-mode');
  console.log('🌙 Dark mode loaded');
}

actions.navigateToPage:
const url = context.actionParams?.url;
if (!url) {
  console.error('❌ No URL provided');
  return;
}
console.log('🧭 Navigating to:', url);
window.location.href = url;
